import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export default function SignIn() {
  const navigate = useNavigate();
  const { login } = useAuth();
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    remember: false,
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value,
    }));
    setError(''); // Clear error on input change
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    // Basic validation
    if (!formData.email || !formData.password) {
      setError('Please fill in all fields');
      setLoading(false);
      return;
    }

    if (!/\S+@\S+\.\S+/.test(formData.email)) {
      setError('Please enter a valid email address');
      setLoading(false);
      return;
    }

    try {
      const result = await login(formData.email, formData.password, formData.remember);

      if (result.success) {
        navigate('/'); // Redirect to home page
      } else {
        setError(result.error || 'Login failed. Please try again.');
      }
    } catch (err) {
      setError('An unexpected error occurred. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-indigo-100 dark:from-gray-900 dark:to-gray-800 px-4">
      <div className="max-w-md w-full space-y-8 bg-white dark:bg-gray-800 p-8 rounded-2xl shadow-xl">
        {/* Header */}
        <div className="text-center">
          <h1 className="text-4xl font-bold text-gray-900 dark:text-white mb-2">
            Welcome Back
          </h1>
          <p className="text-gray-600 dark:text-gray-400">
            Sign in to your EchoScript account
          </p>
        </div>

        {/* Error Message */}
        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 text-red-700 dark:text-red-400 px-4 py-3 rounded-lg">
            {error}
          </div>
        )}

        {/* Form */}
        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Email */}
          <div>
            <label htmlFor="email" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              Email Address
            </label>
            <input
              id="email"
              name="email"
              type="email"
              autoComplete="email"
              required
              value={formData.email}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400 focus:border-transparent bg-white dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
              placeholder="[email protected]"
            />
          </div>

          {/* Password */}
          <div>
            <label htmlFor="password" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
              Password
            </label>
            <input
              id="password"
              name="password"
              type="password"
              autoComplete="current-password"
              required
              value={formData.password}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400 focus:border-transparent bg-white dark:bg-gray-700 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400"
              placeholder="••••••••"
            />
          </div>

          {/* Remember Me & Forgot Password */}
          <div className="flex items-center justify-between">
            <div className="flex items-center">
              <input
                id="remember"
                name="remember"
                type="checkbox"
                checked={formData.remember}
                onChange={handleChange}
                className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
              />
              <label htmlFor="remember" className="ml-2 block text-sm text-gray-700 dark:text-gray-300">
                Remember me
              </label>
            </div>
            <Link to="/reset-password" className="text-sm text-blue-600 dark:text-blue-400 hover:text-blue-500">
              Forgot password?
            </Link>
          </div>

          {/* Submit Button */}
          <button
            type="submit"
            disabled={loading}
            className="w-full flex justify-center py-3 px-4 border border-transparent rounded-lg shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            {loading ? 'Signing in...' : 'Sign In'}
          </button>
        </form>

        {/* Sign Up Link */}
        <div className="text-center">
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Don't have an account?{' '}
            <Link to="/signup" className="font-medium text-blue-600 dark:text-blue-400 hover:text-blue-500">
              Sign up for free
            </Link>
          </p>
        </div>
      </div>
    </div>
  );
}

src/components/EchoAssistantUltra.jsx.content:
// ✅ EchoAssistantUltra.jsx — Enhanced, Optimized, and Advanced
import { Send, Wand2, X } from 'lucide-react';
import { useCallback, useEffect, useRef, useState } from 'react';
import ReactMarkdown from 'react-markdown';

const persona = {
  name: "Echo",
  greeting:
    "Hi, I'm Echo — your smart assistant. Try commands like `/summarize`, `/clarify`, `/lookup`, `/export`, or `/feedback`.",
};

const suggestions = [
  { label: "Summarize Transcript", command: "/summarize" },
  { label: "Clarify a Section", command: "/clarify" },
  { label: "Look Up Topic", command: "/lookup AI models" },
  { label: "Export Content", command: "/export" },
];

const fuzzyMatch = (input) => {
  const clean = input.toLowerCase().trim();
  if (clean.startsWith("/sum")) return { command: "summarize" };
  if (clean.startsWith("/clar")) return { command: "clarify" };
  if (clean.startsWith("/look")) return { command: "lookup", arg: clean.split(" ").slice(1).join(" ") };
  if (clean.startsWith("/feed")) return { command: "feedback" };
  if (clean.startsWith("/exp")) return { command: "export" };
  if (clean.match(/help|tools|suggest/i)) return { command: "suggest" };
  return null;
};

export default function EchoAssistantUltra({
  user = { name: "User", plan: "Free", id: "anon" },
  context = "Dashboard",
  transcript = "",
}) {
  const [open, setOpen] = useState(false);
  const [input, setInput] = useState("");
  const [history, setHistory] = useState([{ role: "assistant", content: persona.greeting }]);
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef();

  const toggle = useCallback(() => setOpen(o => !o), []);

  useEffect(() => {
    const handler = (e) => e.shiftKey && e.key === "A" && toggle();
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [toggle]);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [history]);

  const sendRequest = async (msg, cmd) => {
    setLoading(true);

    const systemPrompt = `You are Echo, a helpful and intuitive assistant. Context: ${context}. Transcript: ${transcript}. Assist clearly and professionally.`;

    try {
      const res = await fetch(`${import.meta.env.VITE_API_BASE}/assistant/ask`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          system_prompt: systemPrompt,
          transcript,
          question: msg,
          history,
          user_id: user.id,
          mode: "auto",
          tone: "friendly",
          voice: "coach",
        }),
      });
      const data = await res.json();
      const reply = data?.response?.trim();

      setHistory((prev) => [
        ...prev,
        { role: "assistant", content: reply || "🤔 I'm not sure I understood that—could you rephrase?" },
      ]);
    } catch {
      setHistory((prev) => [
        ...prev,
        { role: "assistant", content: "⚠️ An error occurred. Please try again." },
      ]);
    } finally {
      setLoading(false);
    }
  };

  const handleSend = (e) => {
    e.preventDefault();
    if (!input.trim()) return;

    const msg = input.trim();
    setInput("");
    setHistory((prev) => [...prev, { role: "user", content: msg }]);

    const cmd = fuzzyMatch(msg); // This is intentionally unused for now to fix other errors first.

    if (cmd?.command === "lookup") {
      setHistory((prev) => [...prev, { role: "assistant", content: `🔎 Looking up **${cmd.arg}**...` }]);
      const t = setTimeout(() => {
        setHistory((prev) => [
          ...prev,
          { role: "assistant", content: "ðŸ“˜ Real-time lookup is coming soon!" },
        ]);
        setLoading(false);
      }, 1200);
      return;
      // This timeout is not cleaned up, but we'll leave it for now to fix build errors first.
    }

    if (cmd?.command === "suggest") {
      setHistory((prev) => [
        ...prev,
        { role: "assistant", content: suggestions.map((s) => `- \`${s.command}\`: ${s.label}`).join("\n") },
      ]);
      setLoading(false);
      return;
    }

    sendRequest(msg);
  };

  return (
    <>
      <button
        onClick={toggle}
        className="fixed bottom-6 right-6 z-50 p-3 bg-gradient-to-tr from-teal-600 to-teal-400 hover:from-teal-700 hover:to-teal-500 text-white rounded-full shadow-xl"
        aria-label="Toggle Echo Assistant"
      >
        <Wand2 className="w-5 h-5" />
      </button>

      {open && (
        <div
          className="fixed bottom-20 right-6 w-80 max-h-[70vh] bg-white dark:bg-zinc-900 border dark:border-zinc-700 rounded-xl shadow-xl z-50 flex flex-col"
        >
            <div className="p-3 border-b dark:border-zinc-700 flex justify-between items-center">
              <h3 className="font-semibold text-sm">Echo Assistant</h3>
              <button onClick={toggle} className="text-zinc-400 hover:text-white">
                <X size={18} />
              </button>
            </div>
            <div className="flex-1 p-3 overflow-y-auto text-sm space-y-4">
              {history.map((item, i) => (
                <div key={i} className={`flex ${item.role === 'user' ? 'justify-end' : ''}`}>
                  <div
                    className={`max-w-[85%] p-2 rounded-lg ${item.role === 'user' ? 'bg-teal-600 text-white' : 'bg-zinc-100 dark:bg-zinc-800'}`}
                  >
                    <ReactMarkdown>{item.content}</ReactMarkdown>
                  </div>
                </div>
              ))}
              <div ref={scrollRef} />
            </div>

            <form onSubmit={handleSend} className="flex p-2 border-t dark:border-zinc-700">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Ask Echo anything..."
                className="flex-1 p-2 rounded bg-zinc-100 dark:bg-zinc-800 text-sm"
              />
              <button type="submit" className="ml-2 bg-teal-600 hover:bg-teal-700 rounded text-white p-2" disabled={loading}>
                <Send size={16} />
              </button>
            </form>
        </div>
      )}
    </>
  );
}

